mapper.select:
select T1.ISSUE_AMT ISSUE_AMT, T1.CONTRACT_NO, T1.SPONSOR,
,T2.TYPE_1 assetType, T2.TYPE_2 accountintType, T2.TYPE_3 taxType, T2.TYPE_6,T2.TYPE_7, T7.DATA_SOURCE dataSource, T4.CUSTOMER_NAME ISSUER_NAME, T6.YIELD*100 referRate, T2.TYPE_9, T2.TYPE_10, T2.TYPE_11, T2.TYPE_12, T1.ISSUER orgClass, FPR.RECOMMENDER recommender, T7.REGULATORY_RATING, T7.IS_RECEIPT, T7.BOND_RISK_TYPE bondRiskType, T8.ACCOUNTING_CLASS_NAME accountingClassName from FIN_PRODUCT T1 left join FIN_PRODUCT_TYPE T2 on T1.FINPROD_ID = T2.FINPROD_ID left join MST_CALENDAR_INFO T3 on T3.CALENDAR_ID = T1.CALENDAR_ID left join MST_CUSTOMER_INFO T4 on T4.CUSTOMER_ID = T1.ISSUER left join FIN_CASH_INFO T5 on T5.FINPROD_ID=T1.FINPROD_ID
and T5.FINPROD_TYPE= #{finprodType,jdbcType=VARCHAR}
and T5.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
left join FIN_CASH_CALC_RULE T6 on T6.CASH_ID=T5.CASH_ID and T6.EFF_DATE = T1.VDATE LEFT JOIN FIN_PRODUCT_RECOMMENT FPR ON FPR.FINPROD_ID = T1.FINPROD_ID left join FIN_PRODUCT_ADD T7 on T7.FINPROD_ID=T1.FINPROD_ID left join FIN_PRODUCT_CLASS T8 on T8.ACCOUNTING_CLASS=T2.TYPE_2 and T8.FINPROD_TYPE=T1.FINPROD_TYPE and T8.ASSET_TYPE=T2.TYPE_1
T1.FINPROD_ID = #{finprodId}
AND T1.FINPROD_MARKET_ID = #{finprodMarketId} AND T1.FINPROD_TYPE = #{finprodType2}

select  CUSTOMER_ID id,
CUSTOMER_NAME text
from MST_CUSTOMER_INFO


		and (CUSTOMER_ID like concat(concat('%',#{search}),'%')
		or CUSTOMER_NAME like concat(concat('%',#{search}),'%'))


		and CUSTOMER_TYPE = #{CUSTOMER_TYPE}



		and (IS_DEPOSIT_BANK = #{IS_DEPOSIT_BANK}
		or IS_FINANCIER = #{IS_FINANCIER})



		and CUSTOMER_ID = #{initValue}

SELECT
A.ACCOUNTING_CLASS accountingClass,
A.ACCOUNTING_CLASS_NAME accountingClassName
FROM
FIN_PRODUCT_CLASS A
WHERE A.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}

	AND A.ASSET_TYPE = #{assetType,jdbcType=VARCHAR}


	AND A.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}


	AND A.BLN_AREA = #{blnArea,jdbcType=VARCHAR}


	AND A.ORG_CLASS = #{orgClass,jdbcType=VARCHAR}


	AND A.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}



		AND A.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}


AND ROWNUM = 1
